BEGIN;

-- 1. 清空旧数据（先删引用表，再删主表；保留 reward_options / campaign_config 配置）
DELETE FROM point_logs;
DELETE FROM redemption_orders;
DELETE FROM submissions;
DELETE FROM score_imports;
DELETE FROM kocs;

-- 2. 新增地址五列（追加在 kocs 表最右）
ALTER TABLE kocs ADD COLUMN IF NOT EXISTS city TEXT DEFAULT '';
ALTER TABLE kocs ADD COLUMN IF NOT EXISTS state TEXT DEFAULT '';
ALTER TABLE kocs ADD COLUMN IF NOT EXISTS postal_code TEXT DEFAULT '';
ALTER TABLE kocs ADD COLUMN IF NOT EXISTS country TEXT DEFAULT '';
ALTER TABLE kocs ADD COLUMN IF NOT EXISTS phone TEXT DEFAULT '';

-- 3. 导入 KOC（94 人）
ON CONFLICT (uid) DO UPDATE SET discord_name = EXCLUDED.discord_name, name = EXCLUDED.name, channel_tag = EXCLUDED.channel_tag, status = EXCLUDED.status, region = EXCLUDED.region, address = EXCLUDED.address, account_id = EXCLUDED.account_id, server = EXCLUDED.server, notes = EXCLUDED.notes, tier = EXCLUDED.tier, city = EXCLUDED.city, state = EXCLUDED.state, postal_code = EXCLUDED.postal_code, country = EXCLUDED.country, phone = EXCLUDED.phone;

-- 4. 期初积分流水（余额 = SUM(point_logs.change)，故每人写一条 manual 流水）

COMMIT;
